# %% PLS FUNCTIONSfrom __future__ import annotationsfrom typing import Anyimport numpy as npimport pandas as pdfrom sklearn.cross_decomposition import PLSRegressionfrom sklearn.metrics import (    mean_absolute_error,    mean_squared_error,    r2_score,)from sklearn.model_selection import (    GroupKFold,    KFold,    cross_val_predict,)def perform_pls(    X,    y,    max_components=15,    cv=5,    groups=None,    scale=False,    shuffle=True,    random_state=42,    selection_metric="rmsecv",):    """    Perform partial least-squares regression with cross-validation.    The function tests different numbers of PLS components, selects the    optimal number, generates cross-validated predictions, and fits a    final PLS model using all samples.    This function expects X to have already been cropped and preprocessed.    Parameters    ----------    X : pandas.DataFrame or array-like of shape (n_samples, n_features)        Predictor matrix, such as preprocessed NIR spectra.        Rows represent samples and columns represent spectral variables.    y : pandas.Series, pandas.DataFrame, or array-like        Continuous response variable.        The first version of this function supports one response variable.    max_components : int, default=15        Maximum number of PLS components to test.        The function automatically reduces this value when it exceeds        the number allowed by the data or cross-validation folds.    cv : int, default=5        Number of cross-validation folds.    groups : array-like or None, default=None        Group labels for grouped cross-validation.        All samples with the same group label are kept in the same fold.        This is useful for technical replicates or repeated measurements        from the same physical sample.    scale : bool, default=False        Passed to sklearn.cross_decomposition.PLSRegression.        False is recommended when X has already been preprocessed and        you do not want every spectral variable autoscaled by the PLS        estimator.    shuffle : bool, default=True        Whether to shuffle samples before ordinary K-fold splitting.        This option is ignored when groups are supplied.    random_state : int or None, default=42        Random seed used for ordinary shuffled K-fold splitting.    selection_metric : {"rmsecv", "maecv"}, default="rmsecv"        Metric used to select the optimal number of components.    Returns    -------    result : dict        Dictionary containing:        model            Final PLSRegression model fitted using all samples.        n_components            Selected number of PLS components.        component_results            DataFrame containing cross-validation metrics for every            tested component number.        y_measured            Measured response values.        y_cv_predicted            Cross-validated predictions.        y_calibration_predicted            Predictions from the final model fitted using all samples.        residuals_cv            Cross-validated residuals, calculated as measured minus            predicted.        residuals_calibration            Calibration residuals.        rmsecv, maecv, r2cv, bias_cv            Cross-validation statistics.        rmsec, maec, r2c, bias_calibration            Calibration statistics.        scores, loadings, weights, coefficients            Parameters extracted from the fitted PLS model.        cv_splits            Training and validation indices used during cross-validation.        sample_names            Sample names taken from X or y when available.        feature_names            Spectral-variable names taken from X when available.    Notes    -----    Cross-validated predictions are produced so that each sample is    predicted by a model that was fitted without that sample.    Residuals are calculated as:        residual = measured - predicted    Examples    --------    >>> result = perform_pls(    ...     X=X_processed,    ...     y=y,    ...     max_components=15,    ...     cv=5,    ... )    >>> result["n_components"]    6    >>> result["rmsecv"]    1.42    >>> result["component_results"]    """    # ------------------------------------------------------------------    # 1. Validate general arguments    # ------------------------------------------------------------------    if not isinstance(max_components, int) or max_components < 1:        raise ValueError(            "'max_components' must be a positive integer."        )    if not isinstance(cv, int) or cv < 2:        raise ValueError(            "'cv' must be an integer greater than or equal to 2."        )    valid_selection_metrics = {"rmsecv", "maecv"}    if selection_metric not in valid_selection_metrics:        raise ValueError(            "'selection_metric' must be one of: "            f"{sorted(valid_selection_metrics)}."        )    # ------------------------------------------------------------------    # 2. Preserve labels before converting to NumPy    # ------------------------------------------------------------------    if isinstance(X, pd.DataFrame):        sample_names = X.index.to_numpy(copy=True)        feature_names = X.columns.to_numpy(copy=True)        X_array = X.to_numpy(dtype=float, copy=True)    else:        X_array = np.asarray(X, dtype=float)        if X_array.ndim != 2:            raise ValueError(                "'X' must be a two-dimensional matrix with shape "                "(n_samples, n_features)."            )        sample_names = np.arange(X_array.shape[0])        feature_names = np.arange(X_array.shape[1])    if isinstance(y, pd.Series):        y_name = y.name        y_array = y.to_numpy(dtype=float, copy=True)    elif isinstance(y, pd.DataFrame):        if y.shape[1] != 1:            raise ValueError(                "This version of perform_pls() supports only one "                "response variable. Supply y with one column."            )        y_name = y.columns[0]        y_array = y.iloc[:, 0].to_numpy(dtype=float, copy=True)    else:        y_name = None        y_array = np.asarray(y, dtype=float)    # Flatten forms such as shape (n_samples, 1)    y_array = np.squeeze(y_array)    if y_array.ndim != 1:        raise ValueError(            "'y' must contain one continuous response variable."        )    # ------------------------------------------------------------------    # 3. Validate dimensions    # ------------------------------------------------------------------    n_samples, n_features = X_array.shape    if n_samples != len(y_array):        raise ValueError(            "X and y contain different numbers of samples: "            f"X has {n_samples}, while y has {len(y_array)}."        )    if n_samples < 3:        raise ValueError(            "At least three samples are required for PLS regression."        )    if n_features < 1:        raise ValueError(            "X must contain at least one predictor variable."        )    if cv > n_samples:        raise ValueError(            f"'cv' cannot exceed the number of samples. "            f"Received cv={cv} and n_samples={n_samples}."        )    # ------------------------------------------------------------------    # 4. Check missing and infinite values    # ------------------------------------------------------------------    if not np.isfinite(X_array).all():        raise ValueError(            "X contains NaN or infinite values. Remove or impute them "            "before running perform_pls()."        )    if not np.isfinite(y_array).all():        raise ValueError(            "y contains NaN or infinite values. Remove or impute them "            "before running perform_pls()."        )    if np.allclose(np.std(y_array, ddof=1), 0):        raise ValueError(            "y has no variation. PLS regression requires a variable "            "response."        )    # ------------------------------------------------------------------    # 5. Construct cross-validation folds    # ------------------------------------------------------------------    if groups is None:        cv_object = KFold(            n_splits=cv,            shuffle=shuffle,            random_state=random_state if shuffle else None,        )        cv_splits = list(            cv_object.split(X_array, y_array)        )        groups_array = None    else:        groups_array = np.asarray(groups)        if len(groups_array) != n_samples:            raise ValueError(                "'groups' must contain one group label per sample."            )        n_unique_groups = np.unique(groups_array).size        if cv > n_unique_groups:            raise ValueError(                "'cv' cannot exceed the number of unique groups. "                f"Received cv={cv} and "                f"{n_unique_groups} unique groups."            )        cv_object = GroupKFold(n_splits=cv)        cv_splits = list(            cv_object.split(                X_array,                y_array,                groups=groups_array,            )        )    # ------------------------------------------------------------------    # 6. Determine the maximum valid component number    # ------------------------------------------------------------------    # PLS components must be valid in every training fold, not only in    # the complete dataset.    minimum_training_size = min(        len(train_index)        for train_index, _ in cv_splits    )    maximum_valid_components = min(        max_components,        n_features,        minimum_training_size - 1,    )    if maximum_valid_components < 1:        raise ValueError(            "The dataset and cross-validation design do not allow even "            "one PLS component."        )    if maximum_valid_components < max_components:        print(            f"Warning: max_components was reduced from "            f"{max_components} to {maximum_valid_components} because "            f"of the dataset size or cross-validation design."        )    # ------------------------------------------------------------------    # 7. Test every component number    # ------------------------------------------------------------------    component_records = []    predictions_by_component = {}    for n_components in range(        1,        maximum_valid_components + 1,    ):        model = PLSRegression(            n_components=n_components,            scale=scale,        )        y_cv_predicted = cross_val_predict(            estimator=model,            X=X_array,            y=y_array,            cv=cv_splits,            method="predict",        )        # PLS predict may return shape (n_samples, 1)        y_cv_predicted = np.asarray(            y_cv_predicted        ).reshape(-1)        residuals_cv = y_array - y_cv_predicted        rmsecv = np.sqrt(            mean_squared_error(                y_array,                y_cv_predicted,            )        )        maecv = mean_absolute_error(            y_array,            y_cv_predicted,        )        r2cv = r2_score(            y_array,            y_cv_predicted,        )        bias_cv = np.mean(residuals_cv)        component_records.append(            {                "n_components": n_components,                "rmsecv": rmsecv,                "maecv": maecv,                "r2cv": r2cv,                "bias_cv": bias_cv,            }        )        predictions_by_component[            n_components        ] = y_cv_predicted    component_results = pd.DataFrame(        component_records    )    # ------------------------------------------------------------------    # 8. Select optimal component number    # ------------------------------------------------------------------    best_row_index = component_results[        selection_metric    ].idxmin()    best_n_components = int(        component_results.loc[            best_row_index,            "n_components",        ]    )    y_cv_predicted = predictions_by_component[        best_n_components    ]    residuals_cv = y_array - y_cv_predicted    # ------------------------------------------------------------------    # 9. Fit final model using all available samples    # ------------------------------------------------------------------    final_model = PLSRegression(        n_components=best_n_components,        scale=scale,    )    final_model.fit(        X_array,        y_array,    )    y_calibration_predicted = final_model.predict(        X_array    ).reshape(-1)    residuals_calibration = (        y_array - y_calibration_predicted    )    # ------------------------------------------------------------------    # 10. Final cross-validation metrics    # ------------------------------------------------------------------    rmsecv = np.sqrt(        mean_squared_error(            y_array,            y_cv_predicted,        )    )    maecv = mean_absolute_error(        y_array,        y_cv_predicted,    )    r2cv = r2_score(        y_array,        y_cv_predicted,    )    bias_cv = np.mean(residuals_cv)    # ------------------------------------------------------------------    # 11. Calibration metrics    # ------------------------------------------------------------------    rmsec = np.sqrt(        mean_squared_error(            y_array,            y_calibration_predicted,        )    )    maec = mean_absolute_error(        y_array,        y_calibration_predicted,    )    r2c = r2_score(        y_array,        y_calibration_predicted,    )    bias_calibration = np.mean(        residuals_calibration    )    # ------------------------------------------------------------------    # 12. Regression slope and intercept for CV predictions    # ------------------------------------------------------------------    prediction_slope, prediction_intercept = np.polyfit(        y_array,        y_cv_predicted,        deg=1,    )    # ------------------------------------------------------------------    # 13. Prepare observation-level output    # ------------------------------------------------------------------    predictions = pd.DataFrame(        {            "sample": sample_names,            "measured": y_array,            "predicted_cv": y_cv_predicted,            "residual_cv": residuals_cv,            "predicted_calibration": (                y_calibration_predicted            ),            "residual_calibration": (                residuals_calibration            ),        },        index=sample_names,    )    # ------------------------------------------------------------------    # 14. Return all results    # ------------------------------------------------------------------    result: dict[str, Any] = {        # Fitted model        "model": final_model,        # Model settings        "n_components": best_n_components,        "max_components_tested": (            maximum_valid_components        ),        "selection_metric": selection_metric,        "scale": scale,        # Input information        "X": X_array,        "y": y_array,        "y_name": y_name,        "sample_names": sample_names,        "feature_names": feature_names,        "groups": groups_array,        # CV information        "cv": cv,        "cv_splits": cv_splits,        # Component optimization        "component_results": component_results,        # Predictions        "predictions": predictions,        "y_measured": y_array,        "y_cv_predicted": y_cv_predicted,        "y_calibration_predicted": (            y_calibration_predicted        ),        # Residuals        "residuals_cv": residuals_cv,        "residuals_calibration": (            residuals_calibration        ),        # Cross-validation statistics        "rmsecv": rmsecv,        "maecv": maecv,        "r2cv": r2cv,        "bias_cv": bias_cv,        # Calibration statistics        "rmsec": rmsec,        "maec": maec,        "r2c": r2c,        "bias_calibration": bias_calibration,        # Prediction-line statistics        "prediction_slope": prediction_slope,        "prediction_intercept": (            prediction_intercept        ),        # PLS latent-variable outputs        "scores": final_model.x_scores_,        "x_scores": final_model.x_scores_,        "y_scores": final_model.y_scores_,        "x_loadings": final_model.x_loadings_,        "y_loadings": final_model.y_loadings_,        "x_weights": final_model.x_weights_,        "y_weights": final_model.y_weights_,        "coefficients": np.asarray(            final_model.coef_        ).reshape(-1),        "x_rotations": final_model.x_rotations_,    }    return result